assets.mkdir(parents=True,exist_ok=True)

css='''
:root{--bg:#f9fafc;--paper:#fff;--ink:#17263d;--muted:#637085;--blue:#103d70;--line:#dce3ee;--soft:#edf3f9;--max:1210px;color-scheme:light}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:85px}body{margin:0;color:var(--ink);background:var(--bg);font-family:Arial,Helvetica,sans-serif;-webkit-font-smoothing:antialiased}body.dark{--bg:#101722;--paper:#172132;--ink:#edf3fb;--muted:#aab9ce;--blue:#a7cbfc;--line:#304259;--soft:#202e43;color-scheme:dark}a{color:inherit;text-decoration:none}button,input{font:inherit}.progress{position:fixed;top:0;left:0;height:3px;background:#4174b7;width:0;z-index:90}.mast{position:sticky;top:0;z-index:20;background:var(--paper);border-bottom:1px solid var(--line)}.nav{max-width:var(--max);padding:0 24px;height:76px;margin:auto;display:flex;gap:32px;align-items:center;justify-content:space-between}.brand{display:flex;flex-direction:column;gap:4px}.brand strong{font:700 27px/1.1 Georgia,'Times New Roman',serif;letter-spacing:-.04em}.brand small{font-size:10px;letter-spacing:.18em;color:var(--muted);text-transform:uppercase}.navlinks{display:flex;align-items:center;gap:29px}.navlinks a{font-size:14px;color:var(--muted)}.navlinks a.active,.navlinks a:hover{color:var(--blue);font-weight:700}.nav-actions{display:flex;gap:8px}.iconbtn{cursor:pointer;border:1px solid var(--line);color:var(--ink);background:var(--paper);padding:9px 12px;border-radius:6px}.iconbtn:hover{border-color:var(--blue)}.wrap{max-width:var(--max);margin:auto;padding:0 24px}.eyebrow{font-size:11px;letter-spacing:.15em;text-transform:uppercase;font-weight:800;color:var(--blue)}.serif{font-family:Georgia,'Times New Roman',serif;letter-spacing:-.035em}.home-hero{margin:36px auto 42px;display:grid;grid-template-columns:1fr 1.02fr;gap:0;background:var(--paper);border:1px solid var(--line);overflow:hidden}.hero-copy{padding:clamp(30px,5vw,64px)}.home-hero h1{font:700 clamp(34px,4.25vw,56px)/1.13 Georgia,'Times New Roman',serif;letter-spacing:-.043em;margin:20px 0 20px}.home-hero p{font-size:16px;line-height:1.77;color:var(--muted);max-width:55ch;margin:0 0 28px}.hero-photo{min-height:390px;object-fit:cover;width:100%;height:100%;display:block;filter:grayscale(.12)}.cta{display:inline-flex;align-items:center;gap:12px;padding:14px 20px;background:#113866;color:white;font-weight:700;font-size:13px;border:1px solid #113866}.cta:hover{background:#235486}.meta{font-size:12px;color:var(--muted);display:flex;gap:17px;align-items:center;flex-wrap:wrap}.meta span+span:before{content:'·';margin-right:16px;color:#8190a6}.section-title{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid var(--line);padding-bottom:13px;margin:42px 0 21px;gap:15px}.section-title h2{margin:0;font:700 30px/1.2 Georgia,'Times New Roman',serif}.section-title span{font-size:12px;color:var(--muted)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:44px;padding-bottom:100px}.articles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.article-card{background:var(--paper);border:1px solid var(--line);display:flex;flex-direction:column;overflow:hidden;transition:transform .18s ease,border-color .18s ease}.article-card:hover{transform:translateY(-3px);border-color:#9fadc0}.article-card img{width:100%;aspect-ratio:1.7;object-fit:cover;display:block}.card-content{padding:20px 19px 22px;display:flex;flex:1;flex-direction:column}.category{color:var(--blue);letter-spacing:.08em;font-size:10px;text-transform:uppercase;font-weight:800}.article-card h3{font:700 24px/1.18 Georgia,'Times New Roman',serif;letter-spacing:-.025em;margin:12px 0}.article-card p{color:var(--muted);font-size:14px;line-height:1.68;margin:0 0 18px}.article-card .meta{margin-top:auto}.empty{border:1px dashed var(--line);color:var(--muted);font-size:14px;padding:35px 25px;line-height:1.7;background:var(--paper)}.side-panel{border-top:2px solid #164d88;padding:18px 0 26px}.side-panel h3{font:700 21px Georgia,'Times New Roman',serif;margin:0 0 13px}.side-panel p{margin:0;color:var(--muted);font-size:14px;line-height:1.75}.topic{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:11px 0;font-size:14px}.topic small{color:var(--muted)}.page-heading{padding:54px 0 12px;border-bottom:1px solid var(--line)}.page-heading h1{font:700 clamp(36px,5vw,54px)/1.13 Georgia,'Times New Roman',serif;margin:12px 0}.page-heading p{line-height:1.7;color:var(--muted);max-width:680px}.filter-row{display:flex;gap:9px;flex-wrap:wrap;margin:22px 0}.filter{padding:9px 14px;border:1px solid var(--line);background:var(--paper);font-size:13px;color:var(--muted);cursor:pointer}.filter.active{background:#113866;border-color:#113866;color:white}.search{border:1px solid var(--line);padding:12px 14px;background:var(--paper);color:var(--ink);width:100%;max-width:350px}.not-found{display:none;color:var(--muted);font-size:14px;padding:34px 0}.about{background:var(--paper);border:1px solid var(--line);padding:42px;margin:28px auto 75px;max-width:800px;line-height:1.85}.article-intro{max-width:970px;margin:48px auto 0}.crumbs{font-size:12px;color:var(--muted);display:flex;gap:10px;flex-wrap:wrap;align-items:center}.article-intro h1{font:700 clamp(37px,5.25vw,68px)/1.12 Georgia,'Times New Roman',serif;letter-spacing:-.046em;margin:24px 0}.article-intro .dek{font:italic 19px/1.68 Georgia,'Times New Roman',serif;color:var(--muted);max-width:900px}.article-intro .meta{margin:18px 0 30px}.article-cover{width:100%;height:auto;aspect-ratio:1.95;object-fit:cover;display:block;border:1px solid var(--line)}.reading-layout{max-width:1090px;margin:44px auto 90px;display:grid;grid-template-columns:minmax(0,720px) 240px;gap:55px;padding:0 24px}.article{font:17px/1.98 Georgia,'Times New Roman',serif;min-width:0}.article p{margin:0 0 24px}.article strong{font-weight:700}.article h2{font:700 32px/1.25 Georgia,'Times New Roman',serif;letter-spacing:-.028em;margin:64px 0 22px;padding-top:22px;border-top:1px solid var(--line)}.article h2:before{content:attr(data-num);display:block;color:var(--blue);font:800 12px Arial,sans-serif;margin-bottom:12px;letter-spacing:.17em}.article-figure{margin:37px 0 45px}.article-figure img{display:block;width:100%;border:1px solid var(--line)}.article-figure figcaption{color:var(--muted);font:12px/1.5 Arial,sans-serif;margin-top:10px}.toc-box{position:sticky;top:106px;align-self:start;border-top:2px solid #164d88;padding-top:19px}.toc-box h3{margin:0 0 13px;font:700 19px Georgia,serif}.toc-box a{display:block;font:13px/1.55 Arial,sans-serif;padding:11px 0;color:var(--muted);border-bottom:1px solid var(--line)}.toc-box a.active,.toc-box a:hover{color:var(--blue)}.summary{background:var(--soft);border-left:3px solid #376da9;padding:20px 22px;margin-bottom:29px;font:15px/1.75 Arial,sans-serif}.summary strong{display:block;letter-spacing:.06em;text-transform:uppercase;color:var(--blue);font:800 11px Arial,sans-serif;margin-bottom:8px}.article-end{border-top:1px solid var(--line);padding:22px 0;margin-top:46px;font:13px Arial,sans-serif}.article-end a{color:var(--blue);font-weight:700}footer{background:var(--paper);border-top:1px solid var(--line);color:var(--muted);font-size:12px;padding:25px 0}.footer-inner{display:flex;justify-content:space-between;gap:20px}.footer-inner a{color:var(--blue)}@media(max-width:930px){.layout{grid-template-columns:1fr}.sidebar{display:none}.reading-layout{grid-template-columns:1fr}.toc-box{position:static;order:-1}.toc-links{display:flex;gap:20px;overflow-x:auto}.toc-box a{min-width:220px;max-width:280px}.home-hero{grid-template-columns:1fr}.hero-photo{height:300px;min-height:0}.navlinks{gap:15px}}@media(max-width:620px){.nav{height:66px;padding:0 16px}.brand strong{font-size:20px}.brand small{font-size:8px}.navlinks{gap:12px}.navlinks a{font-size:12px}.navlinks a[href*="about"]{display:none}.nav-actions{display:none}.wrap{padding:0 16px}.home-hero{margin-top:17px}.hero-copy{padding:24px}.hero-photo{height:205px}.home-hero h1{font-size:34px}.articles{grid-template-columns:1fr}.article-intro{margin-top:27px}.article-intro h1{font-size:37px}.article-intro .dek{font-size:16px}.reading-layout{padding:0 16px;gap:18px}.article{font-size:16px;line-height:1.89}.article h2{font-size:26px}.footer-inner{flex-direction:column}.about{padding:25px}.section-title h2{font-size:26px}}@media print{.mast,.sidebar,.toc-box,.progress,.article-end,footer{display:none!important}.reading-layout{display:block}.article{font-size:12pt}.article-cover{max-height:300px}body{background:white;color:black}}
'''
(out/'styles.css').write_text(css,encoding='utf8')
js='''(()=>{let theme=localStorage.getItem('blog-theme')||'light';if(theme==='dark')document.body.classList.add('dark');document.querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('blog-theme',document.body.classList.contains('dark')?'dark':'light')}));const progress=document.querySelector('.progress');if(progress){let update=()=>{let h=document.documentElement;progress.style.width=(100*scrollY/Math.max(1,h.scrollHeight-innerHeight))+'%';let headings=[...document.querySelectorAll('.article h2')],idx=-1;headings.forEach((h,i)=>{if(h.getBoundingClientRect().top<=160)idx=i});document.querySelectorAll('.toc-box a').forEach((a,i)=>a.classList.toggle('active',i===idx))};addEventListener('scroll',update,{passive:true});update()}let q=document.querySelector('#search'),btns=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('[data-card]')];let category='all';function apply(){let term=(q?.value||'').trim().toLocaleLowerCase('vi');let visible=0;cards.forEach(card=>{let ok=(category==='all'||card.dataset.category===category)&&card.dataset.search.toLocaleLowerCase('vi').includes(term);card.hidden=!ok;card.style.display=ok?'':'none';if(ok)visible++});let empty=document.querySelector('#notfound');if(empty)empty.style.display=visible?'none':'block'}btns.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;btns.forEach(x=>x.classList.toggle('active',x===b));apply()}));q?.addEventListener('input',apply);})();'''
(out/'script.js').write_text(js,encoding='utf8')

def relative(page):return '../' if page=='article' else ''
def shell(page,title,body,desc):
 p=relative(page);active={'home':'index.html','listing':'posts.html','about':'about.html'}.get(page,'posts.html')
 return f'''<!doctype html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f9fafc"><meta name="description" content="{html.escape(desc,quote=True)}"><title>{html.escape(title)} · Data & Business</title><link rel="stylesheet" href="{p}styles.css"></head><body><div class="progress"></div><header class="mast"><div class="nav"><a class="brand" href="{p}index.html"><strong>Data & Business</strong><small>Insights from real-world data work</small></a><nav class="navlinks"><a href="{p}index.html" class="{'active' if page=='home' else ''}">Trang chủ</a><a href="{p}posts.html" class="{'active' if page in ('listing','article') else ''}">Bài viết</a><a href="{p}about.html" class="{'active' if page=='about' else ''}">Giới thiệu</a></nav><div class="nav-actions"><button class="iconbtn" data-theme aria-label="Đổi chế độ sáng/tối">◐</button></div></div></header>{body}<footer><div class="wrap footer-inner"><span>© Data & Business · Independent writing on BI and analytics</span><a href="{p}index.html">Về trang chủ ↑</a></div></footer><script src="{p}script.js" defer></script></body></html>'''

def frontmatter(text):
 _,front,content=text.split('---',2);d={}
 for line in front.strip().splitlines():
  if ':' in line:
   k,v=line.split(':',1);d[k.strip()]=v.strip().strip('"').strip("'")
 return d,content.strip()

renderer=mistune.create_markdown(escape=True)
items=[]
for source_md in sorted(articles.glob('*.md')):
 data,md=frontmatter(source_md.read_text(encoding='utf8'))
 if not all(data.get(k) for k in ['title','slug','category','excerpt']):continue
 content=renderer(md)
 soup=BeautifulSoup(content,'html.parser'); first_h1=soup.find('h1'); first_h1.decompose() if first_h1 else None; h2s=soup.find_all('h2');toc=[]
 for i,heading in enumerate(h2s,1):
  slug=f'section-{i}';heading['id']=slug;heading['data-num']=f'0{i} / SECTION'
  toc.append((slug,heading.get_text()))
 # original markdown's body and headings kept untouched; contextual illustrations injected AFTER section headings
 if len(h2s)>1:
  pic=soup.new_tag('figure',attrs={'class':'article-figure'})
  img=soup.new_tag('img',src='../assets/career-transition-sketch.webp',alt='Tranh chì về việc chuyển đổi từ môi trường FMCG sang phân tích sản phẩm công nghệ',loading='lazy')
  caption=soup.new_tag('figcaption');caption.string='Minh họa: những trải nghiệm BI chuyển dịch từ bối cảnh FMCG sang sản phẩm công nghệ.'
  pic.append(img);pic.append(caption);h2s[-1].insert_after(pic)
 slug=data['slug']; outdir=out/'posts';outdir.mkdir(exist_ok=True)
 toc_html=''.join(f'<a href="#{id}">{html.escape(name)}</a>' for id,name in toc)
 count=len(md.split());reading=max(1,round(count/220))
 body=f'''<div class="wrap"><section class="article-intro"><div class="crumbs"><a href="../index.html">Trang chủ</a><span>›</span><a href="../posts.html">Bài viết</a><span>›</span>{html.escape(data['category'])}</div><h1>{html.escape(data['title'])}</h1><p class="dek">{html.escape(data['excerpt'])}</p><div class="meta"><span>{html.escape(data['category'])}</span><span>Khoảng {reading} phút đọc</span></div><img class="article-cover" src="../{html.escape(data.get('cover','assets/article-library-sketch.webp'))}" alt="Minh họa bút chì về kiểm tra luồng dữ liệu từ ERP đến báo cáo" /></section></div><div class="reading-layout"><article class="article"><div class="summary"><strong>Trong bài viết này</strong>{html.escape(data['excerpt'])}</div>{soup}<div class="article-end"><a href="../posts.html">← Xem các bài viết khác</a></div></article><aside class="toc-box"><h3>Nội dung bài viết</h3><div class="toc-links">{toc_html}</div></aside></div>'''
 (outdir/f'{slug}.html').write_text(shell('article',data['title'],body,data['excerpt']),encoding='utf8')
 items.append({**data,'reading':reading})

# Future-proof index: deliberately list only actual published Markdown files.
card=lambda x: f'''<a data-card data-category="{html.escape(x['category'],quote=True)}" data-search="{html.escape((x['title']+' '+x['excerpt']+' '+x['category']),quote=True)}" class="article-card" href="posts/{html.escape(x['slug'])}.html"><img src="{html.escape(x.get('cover','assets/article-library-sketch.webp'))}" loading="lazy" alt="Minh họa nét chì chủ đề Data và Business Intelligence"><div class="card-content"><span class="category">{html.escape(x['category'])}</span><h3>{html.escape(x['title'])}</h3><p>{html.escape(x['excerpt'])}</p><div class="meta"><span>{x['reading']} phút đọc</span><span>Đọc bài viết →</span></div></div></a>'''
first=items[0] if items else None
home_hero=f'''<section class="home-hero"><div class="hero-copy"><div class="eyebrow">Featured article</div><h1>{html.escape(first['title'])}</h1><p>{html.escape(first['excerpt'])}</p><a class="cta" href="posts/{html.escape(first['slug'])}.html">Đọc bài viết <span>→</span></a></div><img class="hero-photo" src="assets/data-factory-sketch.webp" alt="Minh họa bút chì: luồng dữ liệu ERP từ nhà máy đến BI dashboard" /></section>''' if first else ''
categories=sorted({x['category'] for x in items})
sidebar=f'''<aside class="sidebar"><div class="side-panel"><h3>Về blog</h3><p>Một không gian chia sẻ các quan sát về Business Intelligence, Data Analytics và cách dữ liệu được sử dụng trong công việc thực tế.</p></div><div class="side-panel"><h3>Chủ đề</h3>{''.join(f'<a class="topic" href="posts.html"><span>{html.escape(c)}</span><small>{sum(x['category']==c for x in items)} bài</small></a>' for c in categories)}</div><div class="side-panel"><h3>Thêm bài viết</h3><p>Bạn có thể thêm file Markdown vào thư mục <code>articles/</code>, chạy <code>python build.py</code> để xuất bản bài mới.</p></div></aside>'''
home=f'''<main class="wrap">{home_hero}<div class="section-title"><h2>Bài viết mới</h2><span>{len(items)} bài đã xuất bản</span></div><div class="layout"><section class="articles">{''.join(card(x) for x in items)}</section>{sidebar}</div></main>'''
(out/'index.html').write_text(shell('home','Trang chủ',home,'Chia sẻ góc nhìn thực tế về Data, BI và Analytics.'),encoding='utf8')

filters=''.join(f'<button class="filter" data-filter="{html.escape(c,quote=True)}">{html.escape(c)}</button>' for c in categories)
listing=f'''<main class="wrap"><div class="page-heading"><div class="eyebrow">Explore articles</div><h1>Thư viện bài viết</h1><p>Mỗi bài được tổ chức thành một trang riêng. Duyệt theo chủ đề hoặc tìm kiếm nội dung bạn quan tâm.</p></div><div class="filter-row"><button class="filter active" data-filter="all">Tất cả</button>{filters}<input id="search" type="search" class="search" aria-label="Tìm bài viết" placeholder="Tìm bài viết..."></div><div class="layout"><div><section class="articles">{''.join(card(x) for x in items)}</section><div id="notfound" class="not-found">Không tìm thấy bài viết phù hợp.</div></div>{sidebar}</div></main>'''
(out/'posts.html').write_text(shell('listing','Tất cả bài viết',listing,'Danh sách bài viết về Data, BI và Analytics.'),encoding='utf8')
about=f'''<main class="wrap"><div class="page-heading"><div class="eyebrow">About this blog</div><h1>Về blog</h1><p>Một thư viện các bài viết xoay quanh Data, Business Intelligence và kinh nghiệm từ thực tế công việc.</p></div><div class="about"><h2 class="serif">Data & Business</h2><p>Blog này tập hợp các bài viết về những vấn đề nằm giữa nhu cầu business, hệ thống dữ liệu và báo cáo dùng để ra quyết định. Thay vì tổ chức tất cả vào một trang dài, mỗi bài viết có đường dẫn riêng để chia sẻ và cập nhật.</p><p>Các bài mới sẽ được chia theo chủ đề để người đọc có thể khám phá thuận tiện hơn.</p><a class="cta" href="posts.html">Xem các bài viết →</a></div></main>'''
(out/'about.html').write_text(shell('about','Giới thiệu',about,'Giới thiệu blog Data & Business'),encoding='utf8')
print('Built',len(items),'article(s):',[x['slug'] for x in items])
